mapper.select:
/* ProjectMainDao.getProjectMainList */ select a.odoc_sn , a.user_id , a.odoc_nm , to_char(a.frst_reg_dt, 'YYYY. MM. DD') as frst_reg_dt , a.end_yn , a.odoc_type , CASE WHEN EXISTS ( SELECT 1 FROM t_odoc_dtl c WHERE c.user_id = a.user_id AND c.odoc_sn = a.odoc_sn AND DATE(c.odoc_dt) = (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')::date ) THEN 1 ELSE 0 END AS odoc_yn , to_char(MAX(b.odoc_dt), 'YYYY. MM. DD') as last_odoc_dt , a.odoc_fav_yn , a.odoc_thema_type , CASE WHEN a.stream_mdf_dt is not null AND a.stream_mdf_dt between (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')::date - 1 AND (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul') THEN a.stream_sn ELSE 0 END as stream_sn , a.max_stream_sn from t_odoc_main a left join t_odoc_dtl b on b.odoc_sn = a.odoc_sn and b.user_id = a.user_id where a.user_id = #{userId} and a.del_yn = 'N'
and a.odoc_type = #{odocType}
and a.end_yn = #{endYn}
group by a.odoc_sn, a.user_id, a.odoc_nm, a.frst_reg_dt, a.end_yn, a.odoc_type order by case when a.end_yn = 'N' then 0 else 1 end asc, case when a.odoc_fav_yn = 'Y' then 0 else 1 end asc, a.odoc_sn desc

/* ProjectMainDao.getProjectName */
select
    odoc_nm
from t_odoc_main
where user_id = #{userId}
and odoc_sn = #{odocSn}

mapper.update:
/* ProjectMainDao.updateProject */
update t_odoc_main set
    last_mdf_dt = (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')

        , end_yn = #{endYn}


        , del_yn = #{delYn}


        , odoc_nm = #{odocNm}


        , odoc_fav_yn = #{odocFavYn}


        , odoc_alarm_yn = #{odocAlarmYn}


        , odoc_alarm_time = date_trunc('day', CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul') + #{odocAlarmTime}::time

where user_id = #{userId}
and odoc_sn = #{odocSn}

mapper.insert:
/* ProjectMainDao.insertProject */
insert into t_odoc_main
(
    user_id
    , odoc_nm
    , odoc_type
    , odoc_thema_type
    , odoc_alarm_yn
    , odoc_alarm_time
    , frst_reg_dt
    , last_mdf_dt
)
values
(
    #{userId}
    , #{odocNm}
    , #{odocType}
    , #{odocThemaType}
    , #{odocAlarmYn}
    , date_trunc('day', CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul') + #{odocAlarmTime}::time
    , (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')
    , (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')
)

/* ProjectMainDao.commitProject */
insert into t_odoc_dtl
(
    odoc_sn
    , user_id
    , odoc_dt
    , frst_reg_dt
)
select
    #{odocSn}
    , #{userId}
    , (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')
    , (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')
where not exists (
    select 1
    from t_odoc_dtl d
    where d.odoc_sn = #{odocSn}
    AND d.user_id = #{userId}
    AND d.odoc_dt  >=  (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')::date
    AND d.odoc_dt  <   (CURRENT_TIMESTAMP AT TIME ZONE 'Asia/Seoul')::date + interval '1 day'
)

mapper.select:
/* ProjectMainDao.selectThemaList */ select thema_id , thema_nm , thema_get_method , coalesce(thema_get_day, 0) as thema_get_day , coalesce(thema_get_cd, '') as thema_get_cd , thema_desc from t_thema_main where use_yn = 'Y'
and thema_get_method = 'code' and thema_get_cd = #{themaGetCd}
order by case when thema_get_method = 'free' then 0 when thema_get_method = 'day' then 1 else 2 end asc, thema_id asc

/* ProjectMainDao.selectUserThemaList */
SELECT thema_id FROM t_thema_main WHERE use_yn = 'Y' AND thema_get_method = 'free'
UNION
select thema_id::integer from t_thema_dtl where user_id = #{userId}
and thema_id = #{themaId}::text

mapper.insert:
/* ProjectMainDao.insertUserThema */
insert into t_thema_dtl
(
    thema_id
    , user_id
)
values
(
    #{themaId}
    , #{userId}
)
